using System;
using System.Windows;
using System.Windows.Controls;
namespace StickyNotes;
// A safe-default confirmation shared by account actions; no account data is stored here.
internal sealed class FluentConfirmation:Window {
 internal FluentConfirmation(Window owner,string title,string message,string action){Title=title;Owner=owner;Topmost=owner.Topmost;WindowStartupLocation=WindowStartupLocation.CenterOwner;var work=NoteWindow.WorkArea(owner);Visuals.Base(this,Math.Min(440,work.Width-16),300);SizeToContent=SizeToContent.Height;MaxHeight=work.Height-16;bool dark=Visuals.Dark(((NotesApp)Application.Current).Store.Book.Theme);FluentDesign.ThemeControls(this,dark);var surface=Visuals.Surface(this,dark);surface.Margin=new Thickness(4);surface.Padding=new Thickness(20);surface.CornerRadius=new CornerRadius(12);var panel=new StackPanel();surface.Child=panel;var heading=Visuals.Label(title,20);heading.FontWeight=FontWeights.SemiBold;panel.Children.Add(heading);panel.Children.Add(new ScrollViewer{Content=Visuals.Label(message,14),MaxHeight=Math.Max(60,work.Height-190),VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,Margin=new Thickness(0,12,0,16)});var actions=new System.Windows.Controls.Primitives.UniformGrid{Columns=2};var cancel=Visuals.TextButton("Cancelar",()=>DialogResult=false);cancel.IsCancel=cancel.IsDefault=true;actions.Children.Add(cancel);var accept=Visuals.TextButton(action,()=>DialogResult=true);accept.Content=new TextBlock{Text=action,TextWrapping=TextWrapping.Wrap,TextAlignment=TextAlignment.Center};actions.Children.Add(accept);panel.Children.Add(actions);Loaded+=(_,_)=>{Left=Math.Clamp(Left,work.Left,Math.Max(work.Left,work.Right-ActualWidth));Top=Math.Clamp(Top,work.Top,Math.Max(work.Top,work.Bottom-ActualHeight));cancel.Focus();};}
 internal static bool Ask(Window owner,string title,string message,string action)=>new FluentConfirmation(owner,title,message,action).ShowDialog()==true;
}
